-- chair-step: inverse of read_lane_v2_b3_01_files_file_versions — un-enrolls files.file_versions from read-lane v2 and regenerates it back to the set-form read lane.
delete from iam.read_lane_v2_rollout where token = (select token from platform.entity_types where schema_name = 'files' and table_name = 'file_versions' and is_active);
select iam.apply_rls('files', 'file_versions', (select token from platform.entity_types where schema_name = 'files' and table_name = 'file_versions' and is_active), (select rls_variant from platform.entity_types where schema_name = 'files' and table_name = 'file_versions' and is_active));
